package com.lovemaptually.controller;import com.lovemaptually.auth.CurrentUser;import com.lovemaptually.common.ApiResponse;import com.lovemaptually.dto.request.CreateReviewRequest;import com.lovemaptually.dto.response.*;import com.lovemaptually.service.ReviewService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") @RequiredArgsConstructor public class ReviewController {private final ReviewService service;@PostMapping("/reviews")ResponseEntity<ApiResponse<ReviewResponse>>create(Authentication a,@Valid@RequestBody CreateReviewRequest b){return ResponseEntity.status(201).body(ApiResponse.of(201,"리뷰를 저장했습니다",service.create(CurrentUser.id(a),b)));}@GetMapping("/reviews/{id}")ApiResponse<ReviewResponse>get(Authentication a,@PathVariable long id){return ApiResponse.of(200,"조회했습니다",service.get(id,CurrentUser.id(a),true));}@GetMapping("/groups/{gid}/places/{pid}/reviews")ApiResponse<GroupReviewsResponse>group(Authentication a,@PathVariable long gid,@PathVariable long pid){return ApiResponse.of(200,"조회했습니다",service.groupReviews(gid,pid,CurrentUser.id(a)));}}
